  let context=null,modal=null,player=null,events=[],eventIndex=-1,currentDoc=null,currentConfig=null,playing=false,autoTimer=0,openingTimer=0,typingTimer=0,skipTimer=0,skipMode=false,skipBusy=false,typingFullText='',typeAudio=null,orientationHandler=null,history=[],sceneSource='',cgSource='',activeMusicId='',music=null,menuOpen=false,autoMode=false;
  let dialogueCount=0,lastMusicChangeAt=-Infinity,pendingMusicId='';
  const resolvedAssetIds=new Map();
  async function warmStoryImages(){const owner=player,seen=new Set(),queue=[];for(const event of events){if(['cg','bg'].includes(event.type)&&event.value&&event.value!=='none'&&!seen.has(event.value)){seen.add(event.value);queue.push(event.value);}if(event.type==='sys'&&event.command==='show'){const char=findChar(event.args?.[0]),value=event.args?.[3]||spriteEntry(char)?.images?.[event.args?.[1]||'普通']||char?.avatar;if(value&&!seen.has(value)){seen.add(value);queue.push(value);}continue;}if(event.type!=='dialogue')continue;const char=findChar(event.speaker);if(!char)continue;const customAvatar=characterProfile(char)?.avatar;if(customAvatar&&!seen.has(customAvatar)){seen.add(customAvatar);queue.push(customAvatar);}const entry=spriteEntry(char);const mood=event.emotion||currentConfig.cues?.[event.sourceLineIndex]?.emotion||'普通',value=entry?.images?.[mood]||entry?.images?.普通||char.avatar;if(value&&!seen.has(value)){seen.add(value);queue.push(value);}}let cursor=0;await Promise.allSettled(Array.from({length:Math.min(4,queue.length)},async()=>{while(cursor<queue.length&&owner===player){const value=queue[cursor++];try{const url=await source(value);if(url)await window.OCVnPersona?.imageInfo(url);}catch{}}}));}
