    const event=events[eventIndex];if(event.type==='blank')return next();if(event.type==='shake'){if(!matchMedia('(prefers-reduced-motion: reduce)').matches)player.querySelector('.vnp-canvas').animate([{translate:'0'},{translate:'-3px 1px'},{translate:'3px -1px'},{translate:'0'}],{duration:320});return next();}
