      if(event.type==='bg'){player._pendingActorCommands=[];player._manualSides={};player._actorSides={};player._visible=Object.values(player._manualCast||{});$('vnpSprites')?.querySelectorAll('.vnp-sprite').forEach(node=>{if(!player._manualCast?.[node.dataset.char])node.remove();});sceneSource=await source(event.value);applyScene();}
